########## gemm_coopmat_fp16.comp
     1	#version 450
     2	
     3	#extension GL_KHR_cooperative_matrix : enable
     4	#extension GL_KHR_memory_scope_semantics : enable
     5	#extension GL_EXT_shader_16bit_storage : enable
     6	#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable
     7	
     8	// C = A * B via VK_KHR_cooperative_matrix (RDNA3.5's matrix-multiply
     9	// acceleration). A/B are fp16, accumulated in fp32. TILE_M/N/K are
    10	// specialization constants bound at pipeline-creation time to a shape this
    11	// device actually reports supporting (see vk.PhysicalDevice.CooperativeMatrixShapes) —
    12	// they can't be regular GLSL constants because the native shape is only
    13	// known at runtime, after this shader has already been compiled to SPIR-V.
    14	layout(constant_id = 0) const uint TILE_M = 16;
    15	layout(constant_id = 1) const uint TILE_N = 16;
    16	layout(constant_id = 2) const uint TILE_K = 16;
    17	
    18	// One workgroup == one subgroup (64 threads on this device) computes one
    19	// TILE_M x TILE_N tile of C.
    20	layout(local_size_x = 64) in;
    21	
    22	layout(binding = 0) readonly buffer A { float16_t a[]; };
    23	layout(binding = 1) readonly buffer B { float16_t b[]; };
    24	layout(binding = 2) readonly buffer Scales { float dummy[]; }; // unused, kept for a uniform 4-binding layout
    25	layout(binding = 3) writeonly buffer C { float c[]; };
    26	
    27	layout(push_constant) uniform PC {
    28	    uint M;
    29	    uint N;
    30	    uint K;
    31	    uint block;
    32	} pc;
    33	
    34	void main() {
    35	    uint tileRow = gl_WorkGroupID.y;
    36	    uint tileCol = gl_WorkGroupID.x;
    37	
    38	    coopmat<float16_t, gl_ScopeSubgroup, TILE_M, TILE_K, gl_MatrixUseA> matA;
    39	    coopmat<float16_t, gl_ScopeSubgroup, TILE_K, TILE_N, gl_MatrixUseB> matB;
    40	    coopmat<float, gl_ScopeSubgroup, TILE_M, TILE_N, gl_MatrixUseAccumulator> matC;
    41	
    42	    matC = coopmat<float, gl_ScopeSubgroup, TILE_M, TILE_N, gl_MatrixUseAccumulator>(0.0);
    43	
    44	    uint numTiles = pc.K / TILE_K;
    45	    for (uint t = 0u; t < numTiles; t++) {
    46	        coopMatLoad(matA, a, (tileRow * TILE_M) * pc.K + t * TILE_K, pc.K, gl_CooperativeMatrixLayoutRowMajor);
    47	        coopMatLoad(matB, b, (t * TILE_K) * pc.N + tileCol * TILE_N, pc.N, gl_CooperativeMatrixLayoutRowMajor);
    48	        matC = coopMatMulAdd(matA, matB, matC);
    49	    }
    50	
    51	    coopMatStore(matC, c, (tileRow * TILE_M) * pc.N + tileCol * TILE_N, pc.N, gl_CooperativeMatrixLayoutRowMajor);
    52	}
########## gemm_coopmat_q4.comp
     1	#version 450
     2	
     3	#extension GL_KHR_cooperative_matrix : enable
     4	#extension GL_KHR_memory_scope_semantics : enable
     5	#extension GL_EXT_shader_16bit_storage : enable
     6	#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable
     7	#extension GL_EXT_shader_8bit_storage : enable
     8	#extension GL_EXT_shader_explicit_arithmetic_types_int8 : enable
     9	
    10	// C = A * B, fused single-pass: B is stored as Q4 (packed int4, 2
    11	// nibbles/byte, one float16 scale per block along N per row) and
    12	// dequantized tile-by-tile straight into shared memory, then fed to the
    13	// cooperative-matrix accelerator via coopMatLoad from that shared tile —
    14	// no separate dequant pass or fp16-sized scratch buffer needed. A is fp16.
    15	// TILE_M/N/K are specialization constants bound at pipeline-creation time
    16	// (see vk.PhysicalDevice.CooperativeMatrixShapes), same as
    17	// gemm_coopmat_fp16.comp.
    18	layout(constant_id = 0) const uint TILE_M = 16;
    19	layout(constant_id = 1) const uint TILE_N = 16;
    20	layout(constant_id = 2) const uint TILE_K = 16;
    21	
    22	layout(local_size_x = 64) in;
    23	
    24	layout(binding = 0) readonly buffer A { float16_t a[]; };
    25	layout(binding = 1) readonly buffer B { uint8_t b[]; }; // Q4 packed, 2 signed nibbles per byte
    26	layout(binding = 2) readonly buffer Scales { float16_t scales[]; };
    27	layout(binding = 3) writeonly buffer C { float c[]; };
    28	
    29	layout(push_constant) uniform PC {
    30	    uint M;
    31	    uint N;
    32	    uint K;
    33	    uint block; // quantization block size along N, per row of B
    34	} pc;
    35	
    36	shared float16_t tileB[TILE_K * TILE_N];
    37	
    38	float dequantB(uint k, uint col) {
    39	    uint idx = k * pc.N + col;
    40	    uint byteIdx = idx / 2u;
    41	    uint packedByte = uint(b[byteIdx]);
    42	    int nibble = (idx & 1u) == 0u ? int(packedByte & 0xFu) : int(packedByte >> 4u);
    43	    int signedNibble = nibble - 8; // symmetric range [-8, 7]
    44	    uint blocksPerRow = pc.N / pc.block;
    45	    uint blockIdx = k * blocksPerRow + (col / pc.block);
    46	    return float(signedNibble) * float(scales[blockIdx]);
    47	}
    48	
    49	void main() {
    50	    uint tileRow = gl_WorkGroupID.y;
    51	    uint tileCol = gl_WorkGroupID.x;
    52	    uint tid = gl_LocalInvocationID.x;
    53	
    54	    coopmat<float16_t, gl_ScopeSubgroup, TILE_M, TILE_K, gl_MatrixUseA> matA;
    55	    coopmat<float16_t, gl_ScopeSubgroup, TILE_K, TILE_N, gl_MatrixUseB> matB;
    56	    coopmat<float, gl_ScopeSubgroup, TILE_M, TILE_N, gl_MatrixUseAccumulator> matC;
    57	    matC = coopmat<float, gl_ScopeSubgroup, TILE_M, TILE_N, gl_MatrixUseAccumulator>(0.0);
    58	
    59	    uint numTiles = pc.K / TILE_K;
    60	    uint tileElems = TILE_K * TILE_N;
    61	    for (uint t = 0u; t < numTiles; t++) {
    62	        for (uint e = tid; e < tileElems; e += gl_WorkGroupSize.x) {
    63	            uint lk = e / TILE_N;
    64	            uint ln = e % TILE_N;
    65	            uint k = t * TILE_K + lk;
    66	            uint col = tileCol * TILE_N + ln;
    67	            tileB[e] = float16_t(dequantB(k, col));
    68	        }
    69	        barrier();
    70	
    71	        coopMatLoad(matA, a, (tileRow * TILE_M) * pc.K + t * TILE_K, pc.K, gl_CooperativeMatrixLayoutRowMajor);
    72	        coopMatLoad(matB, tileB, 0, TILE_N, gl_CooperativeMatrixLayoutRowMajor);
    73	        matC = coopMatMulAdd(matA, matB, matC);
    74	        barrier();
    75	    }
    76	
    77	    coopMatStore(matC, c, (tileRow * TILE_M) * pc.N + tileCol * TILE_N, pc.N, gl_CooperativeMatrixLayoutRowMajor);
    78	}

