########## gemv_subgroup.comp
     1	#version 450
     2	
     3	#extension GL_KHR_shader_subgroup_arithmetic : enable
     4	#extension GL_KHR_shader_subgroup_basic : enable
     5	#extension GL_EXT_shader_16bit_storage : enable
     6	#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable
     7	#if defined(PRECISION_Q8) || defined(PRECISION_Q4)
     8	#extension GL_EXT_shader_8bit_storage : enable
     9	#extension GL_EXT_shader_explicit_arithmetic_types_int8 : enable
    10	#endif
    11	
    12	// Same shape as gemv_naive.comp (y = W * x) but one workgroup — assumed to
    13	// be exactly one subgroup (local_size_x must equal this device's subgroup
    14	// size, 64) — per output row, with subgroupAdd reducing the row's partial
    15	// sums instead of a serial loop.
    16	layout(local_size_x = 64) in;
    17	
    18	#if defined(PRECISION_Q8)
    19	layout(binding = 0) readonly buffer W { int8_t w[]; };
    20	layout(binding = 1) readonly buffer Scales { float16_t scales[]; };
    21	#elif defined(PRECISION_Q4)
    22	layout(binding = 0) readonly buffer W { uint8_t w[]; };
    23	layout(binding = 1) readonly buffer Scales { float16_t scales[]; };
    24	#elif defined(PRECISION_F16)
    25	layout(binding = 0) readonly buffer W { float16_t w[]; };
    26	layout(binding = 1) readonly buffer Scales { float dummy[]; };
    27	#else
    28	layout(binding = 0) readonly buffer W { float w[]; };
    29	layout(binding = 1) readonly buffer Scales { float dummy[]; };
    30	#endif
    31	
    32	layout(binding = 2) readonly buffer X { float x[]; };
    33	layout(binding = 3) writeonly buffer Y { float y[]; };
    34	
    35	layout(push_constant) uniform PC {
    36	    uint M;
    37	    uint N;
    38	    uint block;
    39	} pc;
    40	
    41	float loadWeight(uint row, uint n) {
    42	#if defined(PRECISION_Q8)
    43	    uint idx = row * pc.N + n;
    44	    uint blockIdx = row * (pc.N / pc.block) + (n / pc.block);
    45	    return float(w[idx]) * float(scales[blockIdx]);
    46	#elif defined(PRECISION_Q4)
    47	    uint idx = row * pc.N + n;
    48	    uint byteIdx = idx / 2u;
    49	    uint packed = uint(w[byteIdx]);
    50	    int nibble = (idx & 1u) == 0u ? int(packed & 0xFu) : int(packed >> 4u);
    51	    int signedNibble = nibble - 8;
    52	    uint blockIdx = row * (pc.N / pc.block) + (n / pc.block);
    53	    return float(signedNibble) * float(scales[blockIdx]);
    54	#elif defined(PRECISION_F16)
    55	    return float(w[row * pc.N + n]);
    56	#else
    57	    return w[row * pc.N + n];
    58	#endif
    59	}
    60	
    61	void main() {
    62	    uint row = gl_WorkGroupID.x;
    63	    if (row >= pc.M) {
    64	        return;
    65	    }
    66	    float partial = 0.0;
    67	    for (uint n = gl_LocalInvocationID.x; n < pc.N; n += gl_WorkGroupSize.x) {
    68	        partial += loadWeight(row, n) * x[n];
    69	    }
    70	    float total = subgroupAdd(partial);
    71	    if (subgroupElect()) {
    72	        y[row] = total;
    73	    }
    74	}
########## gemv_w8a8.comp
     1	#version 450
     2	
     3	#extension GL_KHR_shader_subgroup_arithmetic : enable
     4	#extension GL_KHR_shader_subgroup_basic : enable
     5	#extension GL_EXT_shader_16bit_storage : enable
     6	#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable
     7	#extension GL_EXT_integer_dot_product : enable
     8	
     9	// y = W*x with BOTH operands int8 ("W8A8"), one subgroup per output row
    10	// (same shape as gemv_subgroup.comp). Unlike the PRECISION_Q8 path in
    11	// gemv_naive.comp/gemv_subgroup.comp (dequantize each weight to float, then
    12	// float-multiply-add against x), this reduces 4 weight/activation elements
    13	// at a time via dotPacked4x8EXT — VK_KHR_shader_integer_dot_product's
    14	// packed-int8 dot instruction (RDNA's V_DOT4_I32_I8) — one instruction
    15	// doing 4 int8 MACs instead of 4 float MACs. Both W and X are stored as
    16	// plain uint words, 4 packed signed int8 lanes per word (the same byte
    17	// layout quantizeQ8 already produces — no repacking needed on the host
    18	// side); no 8-bit storage extension is needed since nothing is read as
    19	// int8_t, only as packed uint32.
    20	//
    21	// Applying each block's scale right after its packed dot (rather than
    22	// accumulating a whole block in integer and scaling once) is mathematically
    23	// equivalent — scale is constant within a block, so distributing the
    24	// multiply over the sum changes nothing but rounding order — and avoids
    25	// needing block boundaries to align with the subgroup's striding over
    26	// words.
    27	layout(local_size_x = 64) in;
    28	
    29	layout(binding = 0) readonly buffer W { uint w[]; };          // M x (N/4) packed int8 words
    30	layout(binding = 1) readonly buffer WScales { float16_t wScales[]; }; // M * (N/block)
    31	layout(binding = 2) readonly buffer X { uint x[]; };          // N/4 packed int8 words
    32	layout(binding = 3) writeonly buffer Y { float y[]; };
    33	
    34	layout(push_constant) uniform PC {
    35	    uint M;
    36	    uint N;
    37	    uint block; // quantization block size along N for W; multiple of 4
    38	    float xScale;
    39	} pc;
    40	
    41	void main() {
    42	    uint row = gl_WorkGroupID.x;
    43	    if (row >= pc.M) {
    44	        return;
    45	    }
    46	    uint wordsPerRow = pc.N / 4u;
    47	    uint wordsPerBlock = pc.block / 4u;
    48	    uint blocksPerRow = pc.N / pc.block;
    49	
    50	    float partial = 0.0;
    51	    for (uint j = gl_LocalInvocationID.x; j < wordsPerRow; j += gl_WorkGroupSize.x) {
    52	        int d = dotPacked4x8EXT(int(w[row * wordsPerRow + j]), int(x[j]));
    53	        uint blockIdx = j / wordsPerBlock;
    54	        partial += float(d) * float(wScales[row * blocksPerRow + blockIdx]);
    55	    }
    56	    float total = subgroupAdd(partial);
    57	    if (subgroupElect()) {
    58	        y[row] = total * pc.xScale;
    59	    }
    60	}
########## gemm_tiled.comp
     1	#version 450
     2	
     3	#if defined(PRECISION_F16) || defined(PRECISION_Q8) || defined(PRECISION_Q4)
     4	#extension GL_EXT_shader_16bit_storage : enable
     5	#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable
     6	#endif
     7	#if defined(PRECISION_Q8) || defined(PRECISION_Q4)
     8	#extension GL_EXT_shader_8bit_storage : enable
     9	#extension GL_EXT_shader_explicit_arithmetic_types_int8 : enable
    10	#endif
    11	
    12	#ifndef TILE
    13	#define TILE 16
    14	#endif
    15	
    16	// C = A * B via classic shared-memory tiling. A is MxK, B is KxN, C is MxN.
    17	// PRECISION_Q8/PRECISION_Q4 quantize only B (the weights), matching
    18	// gemm_naive.comp's scheme: one float16 scale per `block`-sized run of
    19	// columns within a row of B. Each B tile element is dequantized once while
    20	// filling shared memory, same as the plain fp32/fp16 paths, so the inner
    21	// product loop is identical regardless of weight format.
    22	layout(local_size_x = TILE, local_size_y = TILE) in;
    23	
    24	#ifdef PRECISION_F16
    25	layout(binding = 0) readonly buffer A { float16_t a[]; };
    26	#else
    27	layout(binding = 0) readonly buffer A { float a[]; };
    28	#endif
    29	
    30	#if defined(PRECISION_Q8)
    31	layout(binding = 1) readonly buffer B { int8_t b[]; };
    32	layout(binding = 2) readonly buffer Scales { float16_t scales[]; };
    33	#elif defined(PRECISION_Q4)
    34	layout(binding = 1) readonly buffer B { uint8_t b[]; }; // 2 signed nibbles per byte
    35	layout(binding = 2) readonly buffer Scales { float16_t scales[]; };
    36	#elif defined(PRECISION_F16)
    37	layout(binding = 1) readonly buffer B { float16_t b[]; };
    38	layout(binding = 2) readonly buffer Scales { float dummy[]; };
    39	#else
    40	layout(binding = 1) readonly buffer B { float b[]; };
    41	layout(binding = 2) readonly buffer Scales { float dummy[]; };
    42	#endif
    43	layout(binding = 3) writeonly buffer C { float c[]; };
    44	
    45	layout(push_constant) uniform PC {
    46	    uint M;
    47	    uint N;
    48	    uint K;
    49	    uint block; // quantization block size along N; unused for f32/f16
    50	} pc;
    51	
    52	float loadB(uint k, uint col) {
    53	#if defined(PRECISION_Q8)
